import sys

def compute_distance(s1, s2):
    if s1 == s2:
        return 0
    for i in range(min(len(s1), len(s2))):
        if s1[i] != s2[i]:
            return max(len(s1)-i, len(s2)-i)
    return max(len(s1), len(s2))

def find_min_distance(n, strings):
    min_distance = float('inf')
    min_string = ""

    for i in range(n):
        for j in range(i+1, n):
            dist = compute_distance(strings[i], strings[j])
            if dist < min_distance:
                min_distance = dist
                min_string = strings[max(i, j)]

    return min_distance, min_string

