def maxQuests(n, m, towers, quests):
    # Initialize possible moves from towers and quests
    moves = {tower: [{t: 'x', t-1: 'xp'} for t in [t + 1, t - 1, t + xa, t - xa] if 1 <= t <= 10**6] for xa, ya in towers}
    for xb, yb, ti in quests:
        if xb == 1 and yb == 1:  # avoid dividing by zero
            if xa == 1 and ya == 1:
                moves[(1, 1)][xa][(ya - 1) % xa] = 'x'
    
    # Store the quests we've already visited to avoid reprocessing them
    quest_visits = set()
    
    # Queue of quests and their picks
    q = deque([(quests[0][3], k) for k, v in quests])
    while q:
        cur, i = q[0][0][3] - 3, q[0][1]
        if i != 0:
            visited = set(q[0][0][3])
            for j, k in q[i-1:i+2]:
                if len(quest_visits) == m:  # all quests visited and they were chosen at 0,1,3 turns each
                    return m
                if (j, 2) not in visited or (j, 1) not in visited:
                    q.append(((j, 2), len(q)))
                if (k, 1) not in visited:
                    q.append(((k, 1), len(q)))
                for p, choice in [(j, k) if j == k else (j, i), (k, j) if k == j else (k, i)]:
                    if p not in quest_visits and (xa, ya) not in quest_visits:
                        quest_visits.add((p, choice))
                        q.append(((p, choice), len(q)))
        curr = q.popleft()
        m = max(m, len((next(enumerate(qt[0]), i) for i, qt in enumerate(curr[0].items()) if (xa-1+yb) % xa == m-i))
    
    return m

