def factorial(n):
    result = 1
    for i in range(2, n+1):
        result *= i
    return result

def power_modulo(base, exp, mod):
    result = 1
    base = base % mod
    while(exp > 0):
        if(exp % 2 == 1):
            result = (result * base) % mod
        exp = exp >> 1
        base = (base * base) % mod
    return result

def power_modulo_recursive(base, exp, mod):
    if(exp == 0):
        return 1
    elif(exp % 2 == 1):
        return (power_modulo_recursive(base, exp-1, mod) * base) % mod
    else:
        half_exp = power_modulo_recursive(base, exp//2, mod)
        return (half_exp * half_exp) % mod

def solve(n, a):
    mod = 998244353
    total = 1
    for i in range(n-1, n*2-1):
        total = (total * power_modulo_recursive(total, n-1, mod)) % mod 
    return int(total)

