from collections import defaultdict, deque

def get_graph(n, roads):
    graph = defaultdict(list)
    for u, v in roads:
        graph[u].append(v)
    return graph

def bfs(graph, start):
    visited = [False] * (n + 1)
    visited[start] = True
    queue = deque([start])

    while queue:
        node = queue.popleft()
        for neighbor in graph[node]:
            if not visited[neighbor]:
                visited[neighbor] = True
                queue.append(neighbor)
    return visited

def is_important(n, indices):
    for i in range(1, n + 1):
        if not indices[i]:
            continue
        visited = bfs(graph, i)
        indices_copy = indices[:]

        for j in range(1, n + 1):
            indices_copy[j] = indices[j] or visited[j]

        if False in indices_copy:
            return False
    return True

def is_semi_important(n, indices):
    for i in range(1, n + 1):
        indices[i] = not indices[i]
        visited = bfs(graph, i)
        indices[i] = False if False in visited else min(*visited)

def upgrade_cities(n, roads, indices):
    important_indices = [0] * (n + 1)
    for i in range(1, n + 1):
        if is_important(n, indices):
            important_indices[i] = i
        elif is_semi_important(n, indices):
            important_indices[i] = i

    return important_indices

