import sys

def is_good(sequence, A, length):
    ones_count = 0
    zeros_count = 0
    for i in range(len(sequence)):
        if A[sequence[i]-1] == 1:
            ones_count += 1
        else:
            zeros_count += 1
        if ones_count - zeros_count != length:
            return False
    return True

def find_largest_good_sequence(A):
    largest_length = 0
    maximum_indices = []
    for i in range(len(A)):
        for j in range(i+1, len(A)):
            if is_good(sorted([A.index(x) + 1 for x in A if x != 0 and A.index(x) < j]), A, j-i):
                length = j-i
                if length > largest_length:
                    largest_length = length
                    maximum_indices = [x+1 for x in A if A.index(x) < j and A[A.index(x)] == 1]
                    maximum_indices.sort()
    return largest_length, maximum_indices

