import sys

def edit_distance(s1, s2):
    m, n = len(s1), len(s2)
    dp = [[0] * (n + 1) for _ in range(m + 1)]
    for i in range(m + 1):
        dp[i][0] = i
    for j in range(n + 1):
        dp[0][j] = j
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if s1[i - 1] == s2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]
            else:
                dp[i][j] = 1 + min(dp[i - 1][j], dp[i][j - 1], dp[i - 1][j - 1])
    return dp[m][n]

def find_min_edit_distance(strings):
    n = len(strings)
    min_distance = float('inf')
    min_t = ''
    for t in strings:
        current_distance = 0
        for s1, s2 in zip(sorted(strings, key=len), sorted(strings, key=len)[::-1]):
            current_distance += edit_distance(s1, s2)
        current_distance += edit_distance(strings[n-1-len(t):], strings[:n-len(t)])
        if current_distance < min_distance:
            min_distance = current_distance
            min_t = t
    return min_distance, min_t

