from collections import defaultdict

class Tree:
    def __init__(self, n):
        self.parent = defaultdict(int)
        self.children = {}
        self.roots = []
        self.colors = [-1] * (10**9 + 1)
        self.num_black_cells = 0

    def connect(self, x, y):
        if x < y:
            x, y = y, x
        if self.colors[x] == -1:
            if y not in self.children:
                self.children[y] = []
            self.children[y].append(x)
        else:
            for z in self.children[y]:
                self.parent[z] = x
                if self.parent[z] == y or self.colors[x] == self.colors[y]:
                    self.colors[x] = -1
                    self.colors[z] = -1

    def check_paths(self, x, y):
        if self.colors[x] == self.colors[y]:
            return 1
        ans = 0
        queue = [(x, -1)]
        while queue:
            p, cur_parent = queue.pop(0)
            if cur_parent == y:
                ans |= 1
            for o in self.children[p]:
                if self.parent[o] == y:
                    ans |= 2
                if self.parent[o] == p:
                    queue.append((o, p))
        return ans

def solve(m, paths):
    tree = Tree(-1)
    for x1, y1, x2, y2 in paths:
        tree.connect(x2, y2)
        tree.connect(x1, y1)
        tree.connect(x1, y1)
    ans = 0
    for x, val in enumerate(tree.colors):
        if val == -1:
            tree.colors[x] = 1
            path = tree.check_paths(0, x)
            ans = max(ans, path)
            tree.colors[x] = 2
            ans = max(ans, path)
    ans += 1
    return ans

