from collections import deque

def build_tree(m: int, operations: list[tuple[int, int, int, int]]) -> None:
    n = 10**9 + 1
    graph = [[False for _ in range(n)] for _ in range(n)]

    for x1, y1, x2, y2 in operations:
        if x1 + y1 == 0:  # x & y = 0
            graph[x1][y1] = not graph[x1][y1]
            graph[x2][y2] = not graph[x2][y2]

    root = (0, 0)
    for i in range(n - 1, -1, -1):
        graph[root][i] = graph[i][root] = True

    for i, row in enumerate(graph):
        if not row[i]:
            queue = deque([i])
            while queue:
                node = queue.popleft()
                for j in range(n - 1, -1, -1):
                    if graph[node][j]:
                        graph[node][j] = graph[j][node] = False
                        graph[j][node] = graph[node][j] = True
                        queue.append(j)

