        dfs(x1, y1)
        dfs(x2, y2)

def dfs(x1, y1):
    x, y = x1, y1
    while True:
        if graph[x1][x]:
            graph[x][x1] = graph[x][x] = True
            dfs(x1, y1)
            x2, y2 = x, y
            return
        else:
            x1 = x if x1 >= x else x1
            x2 = x if x1 < x else x2
            x = x + (y1 * bool(x1 ^ y1) - y) // 2 if bool(x1 ^ y1) else -float('inf')
            y = y + (x1 * bool(x1 ^ y1) - x) // 2 if bool(x1 ^ y1) else -float('inf')

def BFS(root: tuple[int, int], target: tuple[int, int]) -> bool:
    from collections import deque
    q = deque([(root, 0, 0)])
    parent = defaultdict(lambda: (None, None))

