                break
        else:
            self.a[t] = [self.m[s] + 2]

    def process_request(self, events):
        answers = []
        for event in events:
            if event[0] == '+':
                _, s, t = event[1:]
                if self.g[s].find(t) > -1:
                    gnomes = self.g[s].count(t)
                    self.g[s] = set(x for x in self.g[s] if x != t)
                    insort(self.a[s], gnomes)
            elif event[0] == '?':
                _, s, t = event[1:]
                skeleton = sorted([self.g[s].count(x) for x in self.a[s]])
                if len(skeleton) >= t:
                    answers.append(skeleton[t - 1] if skeleton else 0)
